```python
import boto3
import json
import os
import time
import uuid

client = boto3.client(
    'logs',
    aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
    aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
    region_name=os.getenv('AWS_REGION', 'us-east-1')
)

log_group_name = '/myapp/logs'
log_stream_name = 'default'
correlation_id = f"corr-{uuid.uuid4().hex[:8]}"

# Create log group if not exists
try:
    client.create_log_group(logGroupName=log_group_name)
except client.exceptions.ResourceAlreadyExistsException:
    pass

# Create log stream if not exists
try:
    client.create_log_stream(
        logGroupName=log_group_name,
        logStreamName=log_stream_name
    )
except client.exceptions.ResourceAlreadyExistsException:
    pass

# Get current sequence token
describe_response = client.describe_log_streams(
    logGroupName=log_group_name,
    logStreamNamePrefix=log_stream_name
)
stream_infos = describe_response['logStreams']
if not stream_infos:
    raise Exception("No log stream found")
stream_info = next((s for s in stream_infos if s['logStreamName'] == log_stream_name), stream_infos[0])
sequence_token = stream_info.get('uploadSequenceToken')

# Prepare events with shared correlation_id
base_ts = int(time.time() * 1000)
events = [
    {
        'timestamp': base_ts,
        'message': json.dumps({
            'correlation_id': correlation_id,
            'level': 'INFO',
            'event': 'Request started'
        })
    },
    {
        'timestamp': base_ts + 1000,
        'message': json.dumps({
            'correlation_id': correlation_id,
            'level': 'INFO',
            'event': 'Processing complete'
        })
    },
    {
        'timestamp': base_ts + 2000,
        'message': json.dumps({
            'correlation_id': correlation_id,
            'level': 'INFO',
            'event': 'Request finished'
        })
    }
]

# Put log events
put_kwargs = {
    'logGroupName': log_group_name,
    'logStreamName': log_stream_name,
    'logEvents': events
}
if sequence_token:
    put_kwargs['sequenceToken'] = sequence_token

response = client.put_log_events(**put_kwargs)
print(f"Successfully ingested logs. Next sequence token: {response.get('nextSequenceToken')}")
